CAP='Буквы со штрихами обозначают соответствующие точки образа. Третья модель позволяет проверить вывод после изменения исходных данных.'


def card(n,part,page,task,proof,steps,scenes,checks,rule,hint):
    return entry(n,part,[page],task,proof,steps,scenes,checks,rule,hint,CAP,refs=[133,134,135])


def angle_image(title,angle,k):
    center=(-.6,-1);v=(1,1);a=(3,1);b=(1+2*cos(radians(angle)),1+2*sin(radians(angle)))
    raw={'V':v,'A':a,'B':b};points={'T':center,**raw}
    points.update({key+'′':(center[0]+k*(x-center[0]),center[1]+k*(y-center[1])) for key,(x,y) in raw.items()})
    return diagram(title,points,[('V','A'),('V','B'),('V′','A′'),('V′','B′')])


