def chain_scene(title,first,r1,r2):
    raw=rectangle(first,first*.6);points={};edges=[]
    left=0
    for suffix,scale in [('',1),('′',r1),('″',r1*r2)]:
        names=[]
        for q,(x,y) in raw.items():
            name=q+suffix;points[name]=(x*scale+left,y*scale);names.append(name)
        edges+=list(zip(names,names[1:]+names[:1]));left+=first*scale+1.3
    return diagram(title,points,edges)


